<script setup lang="ts">
import { computed,reactive,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api,run,ui,parse,uid,upload,notify,labels } from './api'
import Fields from './Fields.vue'
import GelObserver from './GelObserver.vue'
const props=defineProps<{recordId?:number,teacher?:boolean}>();const route=useRoute(),router=useRouter()
const draftKey='bio_experiment_draft';const initial={request_id:uid(),abnormality:'无条带',description:'',student_initial_hypothesis:'',positive_control_normal:'未观察',negative_control_band:'未观察',positive_control_detail:'',negative_control_detail:'',band_pattern:'',confirmed_hints:[],course_name:'',class_name:'',group_code:'',experiment_name:'PCR 与电泳实验',teaching_task_code:'',template_amount:null,template_concentration:null,reaction_volume:null,annealing_temp:null,recommended_temp:null,target_size:null,cycles:null,template_type:'待确认',polymerase:'',gel_notes:''}
const draft=reactive<any>({...initial,...parse(sessionStorage.getItem(draftKey))});const step=ref(1),file=ref<File|null>(null),busy=ref(false),record=ref<any>(null),task=ref<any>(null),queryCode=ref(''),revision=reactive({cause:'',reason:''}),plan=reactive<any>({}),retest=reactive<any>({conclusion:'仍无法判断'}),transfer=reactive<any>({minutes:null}),answers=reactive<any>({}),hints=ref<string[]>([]),operation=ref(''),candidates=ref<string[]>([]),retestFile=ref<File|null>(null)
const currentId=computed(()=>props.recordId??(route.params.id?Number(route.params.id):null))
watch(draft,()=>sessionStorage.setItem(draftKey,JSON.stringify(draft)),{deep:true})
async function load(){if(currentId.value)await run(async()=>{record.value=await api('/cases/'+currentId.value);Object.assign(plan,record.value.plan);revision.cause=record.value.student_revised_cause??'';revision.reason=record.value.student_revision_reason??''},'')}
watch(currentId,()=>{record.value=null;load()},{immediate:true})
watch(()=>route.query.task,code=>{if(code)draft.teaching_task_code=String(code)},{immediate:true})
watch(()=>draft.teaching_task_code,async(code)=>{task.value=null;if(code)await run(async()=>task.value=await api('/tasks/'+encodeURIComponent(code)),'')},{immediate:true})
function chooseFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]??null}
async function submit(){busy.value=true;await run(async()=>{await api('/session/guest',{});const created=await api('/cases',draft);queryCode.value=created.query_code;ui.role='student';ui.caseIds=[...new Set([...ui.caseIds,created.id])];let warning='';if(file.value){try{await upload(`/cases/${created.id}/image`,file.value)}catch(e){warning='实验案例已保存，图片上传未完成，请在案例中补传。'+(e as Error).message}}sessionStorage.removeItem(draftKey);Object.assign(draft,{...initial,request_id:uid(),confirmed_hints:[]});await router.push('/cases/'+created.id);notify(warning||'实验案例已保存，请妥善保存私有查询码',!!warning)},'');busy.value=false}
async function action(kind:string,payload:any){busy.value=true;await run(async()=>{await api(`/cases/${currentId.value}/${kind}`,payload);await load()});busy.value=false}
async function saveRetest(){busy.value=true;await run(async()=>{const saved=await api(`/cases/${currentId.value}/retest`,retest);let warning='';if(retestFile.value){try{await upload(`/cases/${currentId.value}/retests/${saved.id}/image`,retestFile.value)}catch(e){warning='复测文字已保存，图片上传失败，可在该复测中补传。'+(e as Error).message}}await load();notify(warning||'实际复测已追加，原记录保留',!!warning)},'');busy.value=false}

function applyScheme(){const payload=parse(task.value?.scheme_json);const values=parse(payload.payload_json);for(const key of Object.keys(initial))if(values[key]!==undefined&&key!=='request_id')draft[key]=values[key];notify('已填入任务发布时的课程方案，请按实际实验核对；未知项保持留空')}
</script>
<template><div v-if="!teacher" class="page-title"><div><p class="eyebrow">证据与反馈</p><h1>{{ui.config.brand?.modules?.experiment.name??'电泳异常分析'}}</h1><p class="muted">{{ui.config.brand?.modules?.experiment.description??'结合实验记录与对照结果分析电泳异常，通过教师反馈和复测验证改进判断'}}</p><p class="muted small">实验专题：PCR 与电泳</p></div><RouterLink to="/knowledge" class="button secondary">查询相关知识</RouterLink></div>
<section v-if="queryCode" class="panel code-panel"><h2>请保存私有查询码</h2><code>{{queryCode}}</code><p>它用于找回此案例及后续反馈，换设备也需要使用。遗失后无法自行找回。</p></section>
<template v-if="!currentId"><div class="steps"><button v-for="(name,i) in ['课堂信息','实验观察','实验条件与初步判断','确认并提交']" :key="name" :class="{active:step===i+1}" @click="step=i+1"><span>{{Number(i)+1}}</span>{{name}}</button></div><form class="panel" @submit.prevent="submit">
<template v-if="step===1"><h2>关联课堂任务</h2><label>任务码（可留空）<input v-model="draft.teaching_task_code" maxlength="30"></label><div v-if="task" class="notice"><b>{{task.title}}</b><p class="preserve">{{task.instructions}}</p><p>{{task.knowledge_note}}</p><div class="chips"><RouterLink v-for="e in task.knowledge.items" :key="e.id" :to="{path:'/knowledge/'+e.id,query:{task:task.code}}">{{e.name}} ↗</RouterLink></div><button type="button" class="secondary" @click="applyScheme">填入任务课程方案</button></div><Fields :data="draft" :fields="['course_name','class_name','group_code','experiment_name']"/></template>
<template v-if="step===2"><h2>记录实际观察</h2><label>主要实验现象<select v-model="draft.abnormality"><option v-for="s in ['无条带','条带弱','多条带或非特异扩增','条带大小不对','条带拖尾或弥散','阴性对照有带','阳性对照无带','条带畸形']" :key="s">{{s}}</option></select></label><div class="fields"><label>阳性对照<select v-model="draft.positive_control_normal"><option v-for="v in ['未观察','未设置','无法确认','是','否']" :key="v">{{v==='是'?'正常':v==='否'?'异常':v}}</option></select></label><label>阳性对照具体表现<select v-model="draft.positive_control_detail"><option value="">尚未分型</option><option v-for="v in ['正常','无带','弱带','异常待分型']" :key="v">{{v}}</option></select></label><label>阴性对照是否有带<select v-model="draft.negative_control_band"><option v-for="v in ['未观察','未设置','无法确认','是','否']" :key="v">{{v==='是'?'有带':v==='否'?'无带':v}}</option></select></label><label>阴性对照具体表现<select v-model="draft.negative_control_detail"><option value="">尚未分型</option><option v-for="v in ['无带','目标大小相近带','小片段带','拖尾或弥散']" :key="v">{{v}}</option></select></label></div><label>原始现象与操作记录<textarea v-model="draft.description" rows="4" maxlength="5000" placeholder="区分观察到的事实与尚待核实的猜测"></textarea></label><label>电泳图（PNG／JPG，不超过10 MB，可稍后补传）<input type="file" accept="image/png,image/jpeg" @change="chooseFile"></label><label>人工泳道说明<textarea v-model="draft.gel_notes" maxlength="2000"></textarea></label><p class="muted small">切换模块后文字保留在当前标签页；离开此表单后，图片需要重新选择。</p></template>
<template v-if="step===3"><h2>填写已知条件并作出初步判断</h2><p class="muted">未知参数保持空白；加入体积和绝对温度本身不能证明异常原因。</p><Fields :data="draft" :fields="['template_type','polymerase','template_concentration','template_amount','reaction_volume','target_size','annealing_temp','recommended_temp','cycles']" :numbers="['template_concentration','template_amount','reaction_volume','target_size','annealing_temp','recommended_temp','cycles']" :options="{template_type:['待确认','质粒','基因组 DNA','cDNA','其他']}"/><label>我的初步判断与依据<textarea v-model="draft.student_initial_hypothesis" required rows="4" maxlength="5000" placeholder="你认为哪些原因值得排查？依据是什么？还有什么不确定？"></textarea></label></template>
<template v-if="step===4"><h2>确认事实后提交</h2><p class="muted">只勾选实际发生、已经核对的事实。候选或猜测不应勾选。</p><label v-for="hint in ui.config.hints" :key="hint" class="check"><input type="checkbox" v-model="draft.confirmed_hints" :value="hint">{{hint}}</label><div class="notice"><b>{{draft.abnormality}}</b><p>初步判断：{{draft.student_initial_hypothesis||'尚未填写，请返回上一步'}}</p><p>已确认事实：{{draft.confirmed_hints.join('、')||'暂无'}}</p></div></template>
<div class="form-actions"><button type="button" v-if="step>1" class="secondary" @click="step--">上一步</button><button type="button" v-if="step<4" @click="step++">下一步</button><button v-else :disabled="busy||!draft.student_initial_hypothesis.trim()||ui.role==='teacher'">{{busy?'正在保存…':'保存实验记录并查看排查建议'}}</button></div><p v-if="ui.role==='teacher'" class="notice">当前为教师身份，请在教师工作区退出后提交学生案例。</p></form></template>
<template v-else-if="record"><section class="panel"><div class="section-head"><div><p class="eyebrow">案例 #{{record.id}}</p><h2>{{record.abnormality}}</h2><p class="muted">{{record.diagnosis_time}} · {{record.class_name||'未填写班级'}} · {{record.group_code||'未填写组号'}}</p></div><a class="button secondary" :href="`/api/v1/cases/${record.id}/report`">导出复盘报告</a></div><h3>我的初步判断</h3><p class="preserve">{{record.student_initial_hypothesis}}</p><h3>原始记录</h3><p class="preserve">{{record.description||'未填写补充记录'}}</p><details><summary>实验参数与原始输入</summary><dl class="entry-fields"><template v-for="(value,key) in record.input" :key="key"><dt>{{labels[key]??key}}</dt><dd>{{Array.isArray(value)?value.join('、'):value??'未知'}}</dd></template></dl></details><p class="notice">以下按规则得分排列排查顺序。得分不代表发生概率，请结合对照、原始记录和复测结果判断。</p><div class="reason-list"><div v-for="(r,i) in record.results" :key="i" class="reason"><span>{{Number(i)+1}}</span><div><h3>{{r['原因']}}</h3><p>{{r['建议']}}</p><ul><li v-for="e in r['诊断依据']?.['证据链']" :key="e">{{e}}</li></ul></div><b>{{r['总分']}}</b></div></div><p v-if="!record.results.length" class="muted">现有信息不足以匹配诊断规则。请补充实验记录，并与教师核实。</p></section>
<section v-if="!teacher&&!record.has_image" class="panel"><h2>补传原始电泳图</h2><input type="file" accept="image/png,image/jpeg" @change="chooseFile"><button :disabled="!file||busy" @click="run(async()=>{await upload(`/cases/${record.id}/image`,file!);await load()},'图片已保存')">上传原图</button></section><GelObserver :record="record" :teacher="teacher" @refresh="load"/>
<section v-if="!teacher&&!record.teacher_final_cause" class="panel"><h2>定向追问与补充证据</h2><p class="muted">未确认的项目保持原样，不需要猜测答案。</p><label v-for="question in record.questions.filter((q:any)=>q.kind==='choice')" :key="question.id">{{question.text}}<select v-model="answers[question.id]"><option :value="undefined">尚未核对</option><option v-for="o in question.options" :key="o">{{o}}</option></select><small>{{question.reason}}</small></label><label>补充操作记录<textarea v-model="operation" rows="3" maxlength="2000"></textarea></label><button class="secondary" :disabled="busy" @click="run(async()=>{const r=await api(`/cases/${record.id}/clues`,{text:operation});candidates=r.candidates},'候选仅供参考，请逐项人工确认')">整理候选事实</button><p v-if="candidates.length">候选：{{candidates.join('、')}}</p><h3>补充确认实际发生的事实</h3><label v-for="h in ui.config.hints" :key="h" class="check"><input type="checkbox" v-model="hints" :value="h">{{h}}</label><button :disabled="busy" @click="action('followup',{answers,hints,operation})">保存补证并更新排查顺序</button></section>
<section class="panel"><h2>教师反馈与学生修订</h2><template v-if="record.teacher_final_cause"><p><b>教师复核：</b>{{record.teacher_final_cause}}</p><p class="preserve">{{record.teacher_note}}</p><p class="muted">{{record.teacher_evidence_level}} · 反馈版本 {{record.teacher_review_version}}</p><p v-if="record.verification_feedback">验证计划反馈：{{record.verification_feedback}}</p><p v-if="record.student_revision_time">已提交修订：{{record.student_revised_cause}} · {{record.student_revision_reason}}</p><form v-if="!teacher&&(!record.student_revision_time||record.student_revision_review_version!==record.teacher_review_version)" @submit.prevent="action('revision',{...revision,version:record.teacher_review_version})"><Fields :data="revision" :fields="['cause','reason']" required/><button :disabled="busy">提交对应当前反馈的修订</button></form></template><p v-else class="muted">等待教师复核，期间可以继续补充证据与设计验证方案。</p></section>
<section class="panel"><h2>验证计划</h2><p class="muted">计划记录不等于实际复测。请说明假设、变量、对照及不同结果怎样解释。</p><Fields :data="plan" :fields="['hypothesis','variable','controls','expected_result','interpretation']" :required="!teacher" :readonly="teacher"/><button v-if="!teacher" :disabled="busy" @click="action('plan',plan)">保存验证计划</button></section>
<section class="panel"><h2>实际复测</h2><div v-for="r in record.retests" :key="r.id" class="retest"><h3>复测 #{{r.id}} · {{r.payload.performed_at}}</h3><dl class="entry-fields"><template v-for="(v,k) in r.payload" :key="k"><dt>{{labels[k]??k}}</dt><dd>{{v}}</dd></template></dl><img v-if="r.has_image" class="gel-image" :src="`/api/v1/cases/${record.id}/retests/${r.id}/image`" alt="实际复测电泳图"><label v-if="!teacher&&!r.has_image&&!r.review">补传本次复测图片<input type="file" accept="image/png,image/jpeg" @change="run(async()=>{const selected=($event.target as HTMLInputElement).files?.[0];if(selected){await upload(`/cases/${record.id}/retests/${r.id}/image`,selected);await load()}},'复测图片已保存')"></label><p v-if="r.review">教师解释：{{r.review.conclusion}} · {{r.review.note}}</p><div v-if="teacher"><Fields :data="r" :fields="['conclusion','note']" :options="{conclusion:['支持原假设','削弱原假设','仍无法判断']}"/><button @click="run(async()=>{await api(`/teacher/retests/${r.id}/review`,{conclusion:r.conclusion,note:r.note,expected_review_id:r.review?.id??null});await load()})">保存复测复核</button></div></div><form v-if="!teacher&&record.plan.hypothesis" @submit.prevent="saveRetest"><Fields :data="retest" :fields="ui.config.retest_fields??[]" :options="{conclusion:['支持原假设','削弱原假设','仍无法判断']}" required/><label>本次复测图片（可选）<input type="file" accept="image/png,image/jpeg" @change="retestFile=($event.target as HTMLInputElement).files?.[0]??null"></label><button :disabled="busy">追加实际复测记录</button></form><p v-else-if="!record.plan.hypothesis" class="muted">先保存验证计划，再追加实际复测。</p></section>
<section v-if="record.task_context.task?.transfer_prompt" class="panel"><h2>新案例独立作答</h2><p>{{record.task_context.task.transfer_prompt}}</p><template v-if="record.task_context.submission"><p>{{record.task_context.submission.answer}}</p><p>{{record.task_context.submission.reasoning}}</p></template><form v-else-if="!teacher" @submit.prevent="action('transfer',transfer)"><Fields :data="transfer" :fields="['answer','reasoning','minutes']" :numbers="['minutes']"/><button :disabled="busy">提交独立作答原稿</button></form></section>
<section class="panel"><h2>版本与教学评价记录</h2><details><summary>查看历次反馈、修订和人工评价</summary><div v-for="h in record.history.teacher" :key="'t'+h.id"><h4>教师反馈版本 {{h.review_version}}</h4><p>{{h.cause}} · {{h.note}}</p></div><div v-for="h in record.history.student" :key="'s'+h.id"><h4>学生修订 · 对应反馈 {{h.review_version}}</h4><p>{{h.cause}} · {{h.reason}}</p></div><div v-for="e in record.history.evaluations" :key="'e'+e.id"><h4>{{({initial:'初判',revised:'修订',transfer:'新案例作答'} as any)[e.stage]}} · 依据版本 {{e.source_version}}</h4><p v-for="(v,k) in parse(e.rubric_json)" :key="k">{{k}}：{{v??'未评价'}}</p><p>{{e.note}}</p></div></details></section>
</template><p v-else class="panel muted">正在读取案例；如会话失效，请返回首页用私有查询码找回。</p></template>
